#pragma once

#include "slabflux/sys/binary_seal.hpp"

namespace slabflux::dist {

    struct beacon_payload {
        uint16_t node_id;
        uint64_t schema_hash;
        char build_id[32];
        uint64_t uptime_ns;
    };

    /**
     * @brief Injected into the Clock Node to pulse identity to the network.
     */
    inline void broadcast_identity(uint16_t id, uint64_t schema) noexcept {
        beacon_payload p;
        p.node_id = id;
        p.schema_hash = schema;
        // Broadcast via stack...
    }
}